using System.Windows.Automation.Peers;
using System.Windows.Controls.Primitives;
using System.Windows.Input;
using Wpf.Zen.Ui.AutomationPeers;

namespace Wpf.Zen.Ui.Controls;

/// <summary>
/// A non-focusable candidate button generated by SoftKeyboardCandidateList. ButtonBase supplies mouse,
/// promoted touch, capture and release-click behavior while the editor retains keyboard focus.
/// </summary>
/// <remarks>
/// Content presents candidate text; candidate identity is maintained separately by the internal host.
/// The template has no named parts; it should present Content and distinguish IsSelected, IsPressed,
/// IsMouseOver and IsEnabled. Instances are created only by the list; the public type supports styling.
/// IsSelected reflects input-method state and never changes as a side effect of clicking.
/// </remarks>
public sealed class SoftKeyboardCandidateItem : ButtonBase
{
    static SoftKeyboardCandidateItem()
    {
        DefaultStyleKeyProperty.OverrideMetadata(
            typeof(SoftKeyboardCandidateItem),
            new FrameworkPropertyMetadata(typeof(SoftKeyboardCandidateItem))
        );

        FocusableProperty.OverrideMetadata(
            typeof(SoftKeyboardCandidateItem),
            new FrameworkPropertyMetadata(false)
        );

        KeyboardNavigation.IsTabStopProperty.OverrideMetadata(
            typeof(SoftKeyboardCandidateItem),
            new FrameworkPropertyMetadata(false)
        );
    }

    // Only the list creates containers. The public type exists so applications can style its template.
    internal SoftKeyboardCandidateItem()
    {
    }

    internal SoftKeyboardCandidate? Candidate { get; private set; }

    internal void SetCandidate(SoftKeyboardCandidate? candidate)
    {
        Candidate = candidate;
        SetCurrentValue(ContentProperty, candidate?.Text);
    }

    private static readonly DependencyPropertyKey IsSelectedPropertyKey
        = DependencyProperty.RegisterReadOnly(
            nameof(IsSelected),
            typeof(bool),
            typeof(SoftKeyboardCandidateItem),
            new PropertyMetadata(false)
        );

    /// <summary>
    /// Identifies the <see cref="IsSelected"/> dependency property.
    /// </summary>
    public static readonly DependencyProperty IsSelectedProperty
        = IsSelectedPropertyKey.DependencyProperty;

    /// <summary>
    /// Gets a value indicating whether the owning list identifies this container as the input method's current candidate.
    /// </summary>
    /// <remarks>
    /// Defaults to false; not inherited or animated by callers. Template triggers update appearance without changing layout.
    /// </remarks>
    public bool IsSelected => (bool)GetValue(IsSelectedProperty);

    internal void SetIsSelected(bool value)
    {
        SetValue(IsSelectedPropertyKey, value);
    }

    /// <inheritdoc />
    protected override AutomationPeer OnCreateAutomationPeer()
    {
        return new SoftKeyboardCandidateItemAutomationPeer(this);
    }

    internal void Invoke()
    {
        // Automation can be queued across page replacement. Detached or disabled containers cannot commit.
        if (IsLoaded && IsEnabled && IsVisible)
        {
            OnClick();
        }
    }
}